import request from 'supertest';
import { Express } from 'express';
import { resetRateLimiterState } from '../../src/middleware/rateLimiter';

describe('Debug Registration', () => {
  let app: Express;

  beforeEach(async () => {
    // Reset rate limiter state to avoid test interference
    resetRateLimiterState();
    
    // Import the actual app
    const appModule = await import('../../src/index');
    app = appModule.app;
  });

  afterEach(async () => {
    jest.clearAllMocks();
  });

  it('should debug registration endpoint', async () => {
    const uniqueEmail = `debug-${Date.now()}@example.com`;
    const testPayload = {
      email: uniqueEmail,
      password: 'TestPassword123!',
      name: 'Debug User',
    };

    console.log('Testing registration with payload:', testPayload);

    const response = await request(app)
      .post('/api/auth/register')
      .send(testPayload);

    console.log('Registration response status:', response.status);
    console.log('Registration response body:', JSON.stringify(response.body, null, 2));
    console.log('Registration response headers:', response.headers);

    // Don't assert anything, just log
  });
});